  "explanation": "慢性肉芽腫症（CGD）では好中球の貪食能は正常だが、NADPHオキシダーゼの欠損によりスーパーオキシドを作れず、貪食した細菌を殺せない。殺しきれない菌が居座るために細胞性免疫が持続的に動員され、異物を囲い込む肉芽腫が形成される。化膿菌による肺炎・リンパ節炎・皮膚炎・肝膿瘍を繰り返すのが臨床像。「貪食できるが殺せない」という一点を押さえる。　▶該当スライド：先天性免疫不全症 p41・p42・p43",
  "choiceNotes": [
   "誤り。カタラーゼは過酸化水素を分解する酵素で、むしろカタラーゼ陽性菌（黄色ブドウ球菌など）がCGD患者で問題になる側。患者側の欠損酵素ではない。",
   "誤り。リゾチームは細菌細胞壁を分解する酵素で、CGDの原因ではない。",
   "正しい＝正解。NADPHオキシダーゼ（gp91-phox など）の欠損で呼吸バーストが起こらない。",
   "誤り。MPO欠損症は別の貪食細胞機能異常症。",
   "誤り。SODはスーパーオキシドを消去する側の酵素。"
  ],
