  "explanation": "免疫チェックポイント阻害薬は、腫瘍を直接叩く薬ではなく、免疫にかかっているブレーキを外す薬である。抗CTLA-4抗体は2方向に効く。ひとつはエフェクターT細胞上のCTLA-4とB7の抑制的な相互作用を遮断してブレーキを外すこと、もうひとつはCTLA-4を高発現する制御性T細胞の抑制機能を弱めることである（Q40）。自分で活性化シグナルを入れるわけではないので、選択肢dは誤り。ブレーキを外す薬なので、有害事象として自己免疫性の障害が起こりうる。　▶該当スライド：T細胞性免疫応答1 p28／T細胞性免疫応答2 p15／自己免疫疾患 p16／腫瘍免疫 p32・p33",
