  "explanation": "インターフェロンはI型（IFN-α・IFN-β）とII型（IFN-γ）に分かれ、役割がはっきり違う。I型はウイルス感染を感知したほぼすべての有核細胞が産生し、感染細胞とその周囲にPKRや2'-5'オリゴアデニル酸合成酵素などの抗ウイルスタンパクを誘導して「抗ウイルス状態」を作る。II型のIFN-γはNK細胞やTh1が作り、マクロファージ活性化とMHC発現増強が主な仕事である（Q49・Q52）。「様々な体細胞が産生」という文言がI型を指している。　▶該当スライド：T細胞性免疫応答2 p3／老化と免疫 p13",
  "choiceNotes": [
   "誤り。IL-2は主にT細胞の増殖因子。",
   "正しい＝正解。I型IFNとして抗ウイルス状態を誘導する。",
   "正しい＝正解。同じくI型IFN。",
   "誤り。II型IFNで、マクロファージ活性化が主な役割。産生細胞もNK細胞・T細胞に限られる。",
   "誤り。TNF-αは炎症性サイトカイン。"
  ],
