  "question": "新生児が母乳由来で得る抗体はどれか。",
  "choices": ["IgA", "IgD", "IgE", "IgG", "IgM"],
  "answer": 0,
  "explanation": "新生児の受動免疫には2つのルートがあり、胎盤を通るのはIgG（FcRnによる能動輸送。Q24）、母乳から届くのは分泌型IgAである。乳腺上皮の基底側にあるポリIg受容体が二量体IgAを捕まえ、トランスサイトーシスで管腔側へ運び、分泌成分を付けたまま乳汁中へ放出する（記述設問3と全く同じ仕組み）。分泌型IgAは分泌成分のおかげで消化酵素に強く、乳児の腸管粘膜で病原体を中和する。",
  "choiceNotes": [
   "正しい＝正解。母乳中に多いのは分泌型IgA。乳児の腸管粘膜を受動免疫で守る。",
   "誤り。IgDはB細胞表面の受容体として働くのが主で、分泌されて働く場面はほとんどない。",
   "誤り。IgEは寄生虫防御とI型アレルギーの抗体（Q23・Q27）。",
   "誤り。IgGは胎盤を通って胎児へ移行する抗体（Q24）。母乳にも少量含まれるが、母乳由来の代表はIgA。",
   "誤り。IgMは分子が大きく胎盤も通らない。新生児血中のIgMは自分で作ったもの＝子宮内感染の指標になる。"
  ],
