  "question": "抗寄生虫(蠕虫)免疫に重要な抗体はどれか。",
  "choices": ["IgA", "IgD", "IgE", "IgG", "IgM"],
  "answer": 2,
  "explanation": "蠕虫（回虫・住血吸虫などの多細胞寄生虫）は大きすぎて貪食できないので、体は「外から囲んで毒を浴びせる」戦法をとる。Th2/ILC2が出すIL-4・IL-5・IL-13により、B細胞はIgEへクラススイッチし、好酸球が増える。虫体に結合したIgEのFc部分を好酸球・肥満細胞・好塩基球のFcε受容体（Q27）が掴み、好酸球が主要塩基性蛋白（MBP）などを放出して傷害する＝ADCC。同じIgEが無害な花粉に向くとI型アレルギーになる（Q51）という表裏の関係も押さえておく。　▶該当スライド：寄生虫・アレルギー p41・42",
  "choiceNotes": [
   "誤り。IgAは粘膜面での中和が主体で、蠕虫の傷害は担わない。",
   "誤り。IgDにこの役割はない。",
   "正しい＝正解。IgEがFcε受容体を介して好酸球・肥満細胞を動員し、蠕虫を攻撃する。",
   "誤り。IgGは細菌・ウイルスに対するオプソニン化と中和が主。",
   "誤り。IgMは初期の補体活性化が主（Q80）。"
  ],
