  "field": "T細胞・サイトカイン",
  "question": "通常型の樹状細胞が産生する IL-12 はどのタイプのサイトカインか。",
  "choices": ["Th1 誘導型サイトカイン", "Th2 誘導型サイトカイン", "Th17 誘導型サイトカイン", "Tfh 誘導型サイトカイン", "Treg 誘導型サイトカイン"],
  "answer": 0,
  "explanation": "通常型樹状細胞（cDC1）は細胞内寄生菌やウイルスを察知するとIL-12を出す。IL-12はナイーブCD4陽性T細胞にT-betを誘導してTh1へ分化させ、同時にNK細胞にIFN-γを産生させる。IFN-γがさらにマクロファージを活性化して細胞内寄生体を殺す——この一連が1型免疫応答である。IL-12/IFN-γ経路の遺伝子に異常があると、弱毒のはずのBCGや非結核性抗酸菌で重い感染症を起こす（メンデル遺伝型抗酸菌症）ことからも、この軸の重要性がわかる。　▶該当スライド：T細胞性免疫応答２ p3・p4／寄生虫・アレルギー p18・19",
  "choiceNotes": [
   "正しい＝正解。IL-12はTh1誘導型サイトカインで、IFN-γ産生とマクロファージ活性化につながる。",
   "誤り。Th2を誘導するのはIL-4（Q43）。",
   "誤り。Th17を誘導するのはIL-6＋TGF-β＋IL-23。",
   "誤り。Tfhの誘導にはIL-6とICOS-Lが関わる。",
   "誤り。Tregの誘導にはTGF-βが関わる。"
  ],
