  "field": "自己免疫疾患",
  "question": "全身性紅斑性狼瘡(SLE)について正しいのはどれか。2 つ選びなさい。",
  "choices": ["若い女性に多い。", "主な皮膚症状は体幹の発赤である。", "患者血中には関節組織に対する自己抗体が出現する。", "自己抗体が糸球体の細胞に結合することでループス腎炎が起こる。", "SLE の活動期にみられる LE 細胞は死んだ細胞の核を貪食した好中球である。"],
  "answer": 0,
  "answers": [0, 4],
  "explanation": "SLEは20〜40代の女性に圧倒的に多い全身性自己免疫疾患で、抗核抗体・抗dsDNA抗体・抗Sm抗体が出る。皮膚症状の代表は体幹ではなく顔面の蝶形紅斑と日光過敏。ループス腎炎の機序は「自己抗体が糸球体細胞に直接結合する」のではなく、DNA–抗DNA抗体などの免疫複合体が糸球体に沈着するIII型である（Q50と対応）。LE細胞は、死んだ細胞から出た核成分に抗核抗体が結合し、それを好中球が貪食した像で、活動期に見られる古典的所見。　▶該当スライド：自己免疫疾患 p42・p44・p45・p46",
  "choiceNotes": [
   "正しい＝正解。若い女性に好発する。",
   "誤り。代表的な皮膚症状は顔面の蝶形紅斑と日光過敏で、体幹の発赤ではない。",
   "誤り。関節組織に対する自己抗体は関節リウマチ側のイメージ。SLEで出るのは抗核抗体など核成分に対する抗体。",
   "誤り。ループス腎炎は免疫複合体の沈着（III型）による。直接結合ではない。",
   "正しい＝正解。LE細胞は核を貪食した好中球で、活動期にみられる。"
  ],
