  "year": "2024年度",
  "category": "免疫学（2年次）",
  "field": "移植免疫",
  "question": "臓器移植をする際に適合させなければいけない HLA 分子の上位 3 つはどれか。3 つ選びなさい。",
  "choices": ["HLA-A", "HLA-B", "HLA-C", "HLA-DRα", "HLA-DRβ"],
  "answer": 0,
  "answers": [0, 1, 4],
  "explanation": "移植で合わせるべきHLAは、多型が大きく＝人によって違いが大きく、拒絶を起こしやすいものから優先される。授業では多型の多い順をB＞DRβ＞Aと整理しており、実際の適合検査もHLA-A・B・DRB1の3座（6抗原）で行う。HLA-Cも多型は多いが優先順位は下がり、HLA-DRα鎖はほとんど多型がないので合わせる必要がない（Q34と表裏）。骨髄移植ではさらに厳密にDNAタイピングで一致を求める。　▶該当スライド：移植免疫 p4",
  "choiceNotes": [
   "正しい＝正解。クラスIの代表として適合の対象になる。",
   "正しい＝正解。HLAの中で最も多型性が高く、最優先で合わせる。",
   "誤り。HLA-Cは多型性はあるが、適合を合わせる上位3つには入らない。",
   "誤り。HLA-DRα鎖はほとんど多型を持たないので適合の対象にならない。",
   "正しい＝正解。DRβ（DRB1）はクラスIIの代表として適合の対象になる。"
  ],
